from pathlib import Path
from collections import Counter,defaultdict
import re
files=[p for p in Path('src/climate').rglob('*') if p.is_file() and p.suffix in {'.cpp','.h','.hpp'}]
canon={str(p):p for p in files}
by_suffix=defaultdict(list)
for s,p in canon.items():
    rel=s.replace('src/','',1)
    by_suffix[rel].append(s)
inc_re=re.compile(r'^\s*#\s*include\s*["<]([^">]+)[">]')
g=defaultdict(set); incoming=Counter(); outgoing=Counter(); unresolved=Counter()
for s,p in canon.items():
    for line in p.read_text(errors='ignore').splitlines():
        m=inc_re.match(line)
        if not m: continue
        x=m.group(1)
        candidates=[]
        if x.startswith('climate/'):
            candidates=by_suffix.get(x,[])
        elif x.startswith('src/climate/'):
            candidates=[x] if x in canon else []
        if len(candidates)==1:
            t=candidates[0]; g[s].add(t)
        elif x.startswith('climate/'):
            unresolved[x]+=1
for s,ts in g.items():
    outgoing[s]=len(ts)
    for t in ts: incoming[t]+=1
print('=== INCLUDE FAN-IN ===')
for p,n in incoming.most_common(30): print(f'{n:3d} {p}')
print('=== INCLUDE FAN-OUT ===')
for p,n in outgoing.most_common(30): print(f'{n:3d} {p}')
print('=== INTERNAL INCLUDE EDGES ===',sum(len(v) for v in g.values()))
# Tarjan SCC
idx=0; stack=[]; on=set(); ids={}; low={}; scc=[]
def dfs(v):
    global idx
    ids[v]=low[v]=idx; idx+=1; stack.append(v); on.add(v)
    for w in g.get(v,()):
        if w not in ids:
            dfs(w); low[v]=min(low[v],low[w])
        elif w in on: low[v]=min(low[v],ids[w])
    if low[v]==ids[v]:
        comp=[]
        while True:
            w=stack.pop(); on.remove(w); comp.append(w)
            if w==v: break
        scc.append(comp)
for v in canon:
    if v not in ids: dfs(v)
cy=[c for c in scc if len(c)>1]
print('=== INCLUDE CYCLES/SCC >1 ===',len(cy))
for c in sorted(cy,key=len,reverse=True): print('SCC',len(c),'|',' | '.join(sorted(c)))
if unresolved:
    print('=== UNRESOLVED climate/ INCLUDES ===')
    for x,n in unresolved.most_common(): print(n,x)
